def f(g, bottom_mode='frag'):
    H=len(g); W=len(g[0]); out=[r[:] for r in g]
    colors=sorted(set(x for r in g for x in r)-{0})
    barrows={i for i in range(H) if any(sum(1 for k in range(W) if g[i][k]==v)>=2 for v in set(x for x in g[i]) if x!=0)}
    def runs_in_row(i):
        row=g[i]; res=[]; j=0
        while j<W:
            if row[j]!=0:
                k=j
                while k<W and row[k]==row[j]: k+=1
                if k-j>=2: res.append((row[j],j,k-1))
                j=k
            else: j+=1
        return res
    for j in range(W):
        # sources scanning from bottom: fragment cells (isolated vertical cells) and bar rows
        srcs=[]
        for i in range(H-1,-1,-1):
            if i in barrows:
                bc=next((v for v,a,b in runs_in_row(i) if a<=j<=b), None)
                srcs.append((i,'bar',bc))
            elif g[i][j]!=0:
                # fragment cell: vertical run length 1 in this column, not in bar row
                run=[p for p in range(max(0,i-1),i+1) if g[p][j]==g[i][j]]
                if len(run)==1: srcs.append((i,'frag',g[i][j]))
        srcs.reverse  # top to bottom
        prev=-1
        for s in srcs:
            r,s_type,c=s
            seg=range(prev+1,r)
            if seg and (r_type := None): pass
            # paint segment with color of 'c' if c not None and this is the bottommost source so far... 
            # rule: bottom-most source paints upward until next source; color = its color ('bar' uses run color, 'frag' its value)
            colc = c if s_type=='bar' else c
            for rr in seg:
                if out[rr][j]==0: out[rr][j]=colc
            prev=r
    return out

