def f(gi):
    H,W=len(gi),len(gi[0])
    out=[r[:] for r in gi]
    bar_rows=set()
    for i in range(H):
        if sum(1 for x in gi[i] if x)>=4: bar_rows.add(i)
    # gap fill
    for i in bar_rows:
        rs=runs(gi[i])
        for j in range(W):
            if gi[i][j]: continue
            L,R=a,b=None,None
            # find runs straddling
            cand=[]
            for (s1,e1,c1),(s2,e2,c2) in zip(rs,rs[1:]):
                if s2==e1+1: cand.append((c1,max(e1-s1+1,e2-s2+1)))
            if cand:
                c=max(cand,key=lambda t:t[1])[0]
                out[i][j]=c
            elif j==0 or gi[i][j-1]!=0:
                # solitary adjacent to run
                run=[r for r in rs if r[1]>=j]
                if run: out[i][j]=run[0][2]
    # arm extension (leftward)
    for i in bar_rows:
        for (a,b,c) in runs(out[i]):
            if b-a+1<2: continue
            step=True
            while step and a>0:
                t=a-1
                if out[i][t-1]!=0: break
                adj=[out[i-1][t] if i>0 else None,out[i+1][t] if i<H-1 else None]
                foreign=[x for x in adj if x is not None and x!=c and any(r[2]==x for r in runs(out[i-1]) if i>0)][:0]
                # simpler: foreign = adjacent row cell at t that is nonzero and not our color
                def is_foreign(r,t_,c_):
                    rr=r_; cc=t_
                    if not(0<=rr<H and 0<=cc<W): return False
                    val=out[rr][cc]
                    if val==c_: return False
                    return True
                fl=[is_foreign(i-1,t,a-1) if i>0 else False,is_foreign(i+1,t,a-1) if i<H-1 else False]
                if not any(fl): break
                a-=1
                if a<0: break
    # vertical fill upward from gap-fill sources
    for j in range(W):
        srcs=sorted([(i,out[i][j]) for i in range(H) if i in bar_rows and gi[i][j]==0 and out[i][j]!=gi[i][j]])
        for r,c in reversed(srcs):
            # fill up while empty, blocked by foreign or edge
            i=r-1
            while i>=0:
                v=out[i][j]
                if v==c: i-=1; continue
                if v!=0: break
                i-=1
            if i>=0:
                for k in range(i+1,r): out[k][j]=c
    return out
